import{_ as a,o as s,c as t,a2 as r}from"./chunks/framework.BWuWLRhz.js";const m=JSON.parse('{"title":"Apariencia y temas","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. Modos de tema","slug":"_1-modos-de-tema","link":"#_1-modos-de-tema","children":[]},{"level":2,"title":"2. Tarjetas de selección de tema","slug":"_2-tarjetas-de-seleccion-de-tema","link":"#_2-tarjetas-de-seleccion-de-tema","children":[{"level":3,"title":"Temas integrados y paquetes incluidos","slug":"temas-integrados-y-paquetes-incluidos","link":"#temas-integrados-y-paquetes-incluidos","children":[]},{"level":3,"title":"Extensibilidad de temas mediante plugins","slug":"extensibilidad-de-temas-mediante-plugins","link":"#extensibilidad-de-temas-mediante-plugins","children":[]}]}],"relativePath":"es-ES/user-guide/settings/appearance.md","filePath":"es-ES/user-guide/settings/appearance.md","lastUpdated":1791112464000}'),o={name:"es-ES/user-guide/settings/appearance.md"};function n(i,e,l,d,c,u){return s(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="apariencia-y-temas" tabindex="-1">Apariencia y temas <a class="header-anchor" href="#apariencia-y-temas" aria-label="Permalink to &quot;Apariencia y temas&quot;">​</a></h1><p>Lertaro admite cambio de modo de tema y varias paletas de color. La página de Apariencia se encuentra en la parte inferior de la barra lateral izquierda (justo encima de &quot;Acerca de&quot;).</p><h2 id="_1-modos-de-tema" tabindex="-1">1. Modos de tema <a class="header-anchor" href="#_1-modos-de-tema" aria-label="Permalink to &quot;1. Modos de tema&quot;">​</a></h2><p>En la parte superior se presentan tres tarjetas de selección:</p><ul><li><strong>Modo Claro</strong>: Fija la interfaz en una estética luminosa; la cuadrícula inferior muestra únicamente los temas de estilo claro.</li><li><strong>Modo Oscuro</strong>: Fija la interfaz en una estética oscura; la cuadrícula inferior muestra únicamente los temas de estilo oscuro.</li><li><strong>Seguir al sistema</strong>: Alterna automáticamente entre dos temas seleccionados según el modo claro u oscuro de Windows. En este modo, la cuadrícula se divide en <strong>Tema claro</strong> y <strong>Tema oscuro</strong>, permitiéndote elegir esquemas distintos para el día y la noche sin reiniciar la aplicación.</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Lertaro recuerda de forma independiente tus temas elegidos para el estilo claro y oscuro, preservando tu selección al alternar modos.</p></div><h2 id="_2-tarjetas-de-seleccion-de-tema" tabindex="-1">2. Tarjetas de selección de tema <a class="header-anchor" href="#_2-tarjetas-de-seleccion-de-tema" aria-label="Permalink to &quot;2. Tarjetas de selección de tema&quot;">​</a></h2><p>Los temas se presentan en una cuadrícula interactiva. Cada tarjeta renderiza una miniatura fiel con la barra de búsqueda, sombras, jerarquía tipográfica y fila resaltada. El tema activo incluye un distintivo de verificación.</p><h3 id="temas-integrados-y-paquetes-incluidos" tabindex="-1">Temas integrados y paquetes incluidos <a class="header-anchor" href="#temas-integrados-y-paquetes-incluidos" aria-label="Permalink to &quot;Temas integrados y paquetes incluidos&quot;">​</a></h3><ul><li><strong>Temas centrales integrados (CoreExtensions)</strong>: <ul><li><strong>Claro (Light)</strong> / <strong>Oscuro (Dark)</strong>: Diseños minimalistas y limpios integrados con la estética nativa de Windows.</li><li><strong>Azul nórdico (Nordic Blue)</strong>: Estilo elegante en tonos fríos con detalles azul hielo sobre fondo azul marino.</li><li><strong>Rosa sakura (Sakura Pink)</strong>: Paleta suave y fresca en tonos pastel blanco y rosa.</li><li><strong>Ciberpunk (Cyberpunk)</strong>: Alto contraste entre amarillo neón y púrpura medianoche de estética futurista.</li></ul></li><li><strong>Temas Anime (AnimeThemes, incluidos)</strong>: <ul><li><strong>Evangelion</strong>, <strong>Sakura Blossom</strong> y <strong>Weathering with You</strong>.</li></ul></li><li><strong>Parejas de temas seleccionados (Curated Themes, incluidos)</strong>: <ul><li>20 combinaciones emparejadas claro/oscuro: <strong>Glaciar</strong>, <strong>Terracota</strong>, <strong>Bosque</strong>, <strong>Amatista</strong>, <strong>Carmesí</strong>, <strong>Grafito</strong>, <strong>Índigo</strong>, <strong>Menta</strong>, <strong>Champán</strong>, <strong>Ámbar</strong>, <strong>Rosé</strong>, <strong>Azul cerceta</strong>, <strong>Matcha</strong>, <strong>Moca</strong>, <strong>Obsidiana</strong>, <strong>Coral atardecer</strong>, <strong>Lavanda</strong>, <strong>Verde salvia</strong>, <strong>Pergamino</strong> y <strong>Azul cobalto</strong>.</li></ul></li></ul><h3 id="extensibilidad-de-temas-mediante-plugins" tabindex="-1">Extensibilidad de temas mediante plugins <a class="header-anchor" href="#extensibilidad-de-temas-mediante-plugins" aria-label="Permalink to &quot;Extensibilidad de temas mediante plugins&quot;">​</a></h3><p>Todos los temas cumplen las especificaciones estándar de <code>Lertaro.PluginSdk</code>. Los desarrolladores pueden crear y distribuir plugins de temas propios para añadir nuevas paletas a esta cuadrícula.</p>',12)])])}const p=a(o,[["render",n]]);export{m as __pageData,p as default};
